class stringx
{
  char data_[8];

public:
  stringx();
  stringx(const char *);
  stringx(const stringx &);
  ~stringx();
  stringx &operator=(const stringx &);
  const char *data() const;
};

stringx operator+(const stringx &, const char *);
stringx operator+(const char *, const stringx &);

class os_developer_options
{
public:
  enum
  {
    STRING_TEXTURE_DIR
  };

  static os_developer_options *inst();
  stringx get_string(int) const;
};

extern void nglSetTexturePath(const char *);

class PanelGeom
{
public:
  virtual void Reload();
  char padding[104];
  PanelGeom *next;
};

class PanelFile
{
  int slide_state;
  float slide_offset;
  float slide_timer;
  float slide_max_time;
  stringx filename;

public:
  PanelGeom *obs;
  stringx path;
  static stringx texture_path;
  static stringx common_path;

  void Reload();
};

void PanelFile::Reload()
{
  texture_path =
    os_developer_options::inst()->get_string(
      os_developer_options::STRING_TEXTURE_DIR) + "\\";
  common_path = "interface\\FE\\common\\" + texture_path;
  nglSetTexturePath((path + texture_path).data());

  PanelGeom *tmp = obs;
  while (tmp)
  {
    tmp->Reload();
    tmp = tmp->next;
  }
}
